func (t CatalogObject) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "Group":
		return t.AsGroup()
	case "Pool":
		return t.AsPool()
	case "Provider":
		return t.AsProvider()
	case "Queue":
		return t.AsQueue()
	case "Rule":
		return t.AsRule()
	case "RuleSet":
		return t.AsRuleSet()
	case "TaskSpec":
		return t.AsTaskSpec()
	case "Template":
		return t.AsTemplate()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

