// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// List agents
	// (GET /agents)
	ListAgents(ctx context.Context, request ListAgentsRequestObject) (ListAgentsResponseObject, error)
	// Register an agent
	// (POST /agents)
	RegisterAgent(ctx context.Context, request RegisterAgentRequestObject) (RegisterAgentResponseObject, error)
	// Deregister an agent
	// (DELETE /agents/{id})
	DeregisterAgent(ctx context.Context, request DeregisterAgentRequestObject) (DeregisterAgentResponseObject, error)
	// Update an agent's status or lending
	// (PATCH /agents/{id})
	UpdateAgent(ctx context.Context, request UpdateAgentRequestObject) (UpdateAgentResponseObject, error)
	// Long-poll for a task
	// (GET /agents/{id}/lease)
	LeaseTask(ctx context.Context, request LeaseTaskRequestObject) (LeaseTaskResponseObject, error)
	// Finish the GitHub OAuth login
	// (GET /auth/callback)
	AuthCallback(ctx context.Context, request AuthCallbackRequestObject) (AuthCallbackResponseObject, error)
	// Device-flow configuration for agent owners
	// (GET /auth/device-config)
	GetDeviceConfig(ctx context.Context, request GetDeviceConfigRequestObject) (GetDeviceConfigResponseObject, error)
	// Start the GitHub OAuth login
	// (GET /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Sign out
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Who am I
	// (GET /auth/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// Get the loaded catalog
	// (GET /catalog)
	GetCatalog(ctx context.Context, request GetCatalogRequestObject) (GetCatalogResponseObject, error)
	// Evaluate an event against the catalog
	// (POST /catalog/dry-run)
	DryRunCatalog(ctx context.Context, request DryRunCatalogRequestObject) (DryRunCatalogResponseObject, error)
	// Get one catalog object
	// (GET /catalog/{kind}/{name})
	GetCatalogObject(ctx context.Context, request GetCatalogObjectRequestObject) (GetCatalogObjectResponseObject, error)
	// Run an operator command
	// (POST /commands)
	PostCommand(ctx context.Context, request PostCommandRequestObject) (PostCommandResponseObject, error)
	// Hand a leased task back
	// (POST /leases/{id}/abandon)
	AbandonLease(ctx context.Context, request AbandonLeaseRequestObject) (AbandonLeaseResponseObject, error)
	// Complete a lease with a Result
	// (POST /leases/{id}/complete)
	CompleteLease(ctx context.Context, request CompleteLeaseRequestObject) (CompleteLeaseResponseObject, error)
	// Extend a lease and report progress
	// (POST /leases/{id}/heartbeat)
	HeartbeatLease(ctx context.Context, request HeartbeatLeaseRequestObject) (HeartbeatLeaseResponseObject, error)
	// List pools with their agents
	// (GET /pools)
	ListPools(ctx context.Context, request ListPoolsRequestObject) (ListPoolsResponseObject, error)
	// List providers with their health
	// (GET /providers)
	ListProviders(ctx context.Context, request ListProvidersRequestObject) (ListProvidersResponseObject, error)
	// List queues with their depth
	// (GET /queues)
	ListQueues(ctx context.Context, request ListQueuesRequestObject) (ListQueuesResponseObject, error)
	// Get a run with its effects
	// (GET /runs/{id})
	GetRun(ctx context.Context, request GetRunRequestObject) (GetRunResponseObject, error)
	// Download a run's transcript
	// (GET /runs/{id}/transcript)
	GetTranscript(ctx context.Context, request GetTranscriptRequestObject) (GetTranscriptResponseObject, error)
	// Upload a run's transcript
	// (PUT /runs/{id}/transcript)
	UploadTranscript(ctx context.Context, request UploadTranscriptRequestObject) (UploadTranscriptResponseObject, error)
	// Subscribe to live updates
	// (GET /stream)
	StreamEvents(ctx context.Context, request StreamEventsRequestObject) (StreamEventsResponseObject, error)
	// List tasks
	// (GET /tasks)
	ListTasks(ctx context.Context, request ListTasksRequestObject) (ListTasksResponseObject, error)
	// Get a task
	// (GET /tasks/{id})
	GetTask(ctx context.Context, request GetTaskRequestObject) (GetTaskResponseObject, error)
	// Get one fetched context item
	// (GET /tasks/{id}/context/{n})
	GetTaskContext(ctx context.Context, request GetTaskContextRequestObject) (GetTaskContextResponseObject, error)
	// Apply (or record) an effect
	// (POST /tasks/{id}/effects)
	CreateEffect(ctx context.Context, request CreateEffectRequestObject) (CreateEffectResponseObject, error)
	// Get a task's rendered prompt
	// (GET /tasks/{id}/prompt)
	GetTaskPrompt(ctx context.Context, request GetTaskPromptRequestObject) (GetTaskPromptResponseObject, error)
	// List work items
	// (GET /workitems)
	ListWorkItems(ctx context.Context, request ListWorkItemsRequestObject) (ListWorkItemsResponseObject, error)
	// Get a work item with its timeline
	// (GET /workitems/{id})
	GetWorkItem(ctx context.Context, request GetWorkItemRequestObject) (GetWorkItemResponseObject, error)
}

